import numpy as np

def aggregate_forces(sigma, epsilon, positions):
    N = len(positions)
    forces = np.zeros((N, 3))

    for i in range(N):
        for j in range(i+1, N):
            force_i_j = calculate_lj_force(sigma, epsilon, positions[i], positions[j])
            forces[i] -= force_i_j
            forces[j] += force_i_j

    return forces

def calculate_lj_force(sigma, epsilon, pos_i, pos_j):
    r = np.linalg.norm(pos_i - pos_j)
    if r > sigma:
        return 0.0
    else:
        f = 24 * epsilon / (sigma ** 13) * ((sigma/r)**12 - 1) * (pos_i - pos_j) / r
        return f
